/**
 * WhatsApp Phone Number Normalizer for Brazil
 *
 * This function normalizes Brazilian phone numbers to WhatsApp format.
 * It handles various input formats:
 * - With/without country code (55)
 * - With/without 9th digit
 * - Different separators (spaces, dashes, parentheses)
 *
 * Output format: 55DDXXXXXXXX@s.whatsapp.net
 */
function normalizeWhatsAppNumber(contact) {
  if (!contact) {
    throw new Error('Contact not provided');
  }

  // Remove all non-numeric characters
  let cleanNumber = contact.toString().replace(/\D/g, '');

  // Remove country code if exists
  if (cleanNumber.startsWith('55')) {
    cleanNumber = cleanNumber.substring(2);
  }

  let result = '';

  // Analyze length to determine format
  if (cleanNumber.length === 11) {
    // Format: DD 9 XXXX-XXXX (11 digits with 9th digit)
    // Get DDD (first 2) + last 8 digits
    const ddd = cleanNumber.substring(0, 2);
    const number = cleanNumber.slice(-8);
    result = `55${ddd}${number}`;

  } else if (cleanNumber.length === 10) {
    // Format: DD XXXX-XXXX (10 digits - landline or old mobile)
    // Keep as is
    result = `55${cleanNumber}`;

  } else if (cleanNumber.length === 9) {
    // Probably 9 XXXX-XXXX (missing DDD)
    console.warn('Number without DDD - using as is');
    result = `55${cleanNumber}`;

  } else {
    // Other cases - use as is
    result = `55${cleanNumber}`;
  }

  return `${result}@s.whatsapp.net`;
}

const normalizedContact = normalizeWhatsAppNumber($json.contato);

return {
  ...$json,
  original_contact: $json.contato,
  contato_normalizado: normalizedContact
};

