/**
 * DateTime Normalizer for Reminder Scheduling
 *
 * Converts the reminder datetime to UTC ISO format
 * and gets current time in UTC for comparison.
 * This ensures accurate scheduling across timezones.
 */

// Get reminder datetime string
let dateString = $json.data_e_hora_lembrete;

// Remove extra double quotes if present
if (typeof dateString === 'string') {
  dateString = dateString.replace(/^"(.*)"$/, '$1');
}

// Convert to UTC ISO format
const reminderDateUTC = new Date(dateString).toISOString();
const currentDateUTC = new Date().toISOString();

return {
  ...$json,
  data_lembrete_utc: reminderDateUTC,
  data_atual_utc: currentDateUTC
};
